-- Fill process on lots that lack one
UPDATE ref_coffees SET process_id=(SELECT e.process_id FROM _coe_enrich e WHERE e.url=ref_coffees.url) WHERE process_id IS NULL AND url IN (SELECT url FROM _coe_enrich WHERE process_id IS NOT NULL);
-- Fill producer altitude/owner/hectares from their enriched lots (keep existing non-null)
UPDATE ref_producers SET altitude_min_m=COALESCE(altitude_min_m,(SELECT e.alt_min FROM _coe_enrich e JOIN ref_coffees c ON c.url=e.url WHERE c.producer_id=ref_producers.id AND e.alt_min IS NOT NULL LIMIT 1)), altitude_max_m=COALESCE(altitude_max_m,(SELECT e.alt_max FROM _coe_enrich e JOIN ref_coffees c ON c.url=e.url WHERE c.producer_id=ref_producers.id AND e.alt_max IS NOT NULL LIMIT 1)), owner=COALESCE(owner,(SELECT e.owner FROM _coe_enrich e JOIN ref_coffees c ON c.url=e.url WHERE c.producer_id=ref_producers.id AND e.owner IS NOT NULL LIMIT 1)), hectares=COALESCE(hectares,(SELECT e.hect FROM _coe_enrich e JOIN ref_coffees c ON c.url=e.url WHERE c.producer_id=ref_producers.id AND e.hect IS NOT NULL LIMIT 1)) WHERE id IN (SELECT c.producer_id FROM _coe_enrich e JOIN ref_coffees c ON c.url=e.url);
-- Variety links (OR IGNORE drops dup PKs and any FK-unmet variety)
INSERT OR IGNORE INTO ref_coffee_varieties (coffee_id,variety_id) SELECT c.id, v.variety_id FROM _coe_enrich_var v JOIN ref_coffees c ON c.url=v.url;
DROP TABLE _coe_enrich;
DROP TABLE _coe_enrich_var;
